function longestMirrorLength(s: string): number {
  const waiting = new Set<string>();
  let total = 0;
  for (const ch of s) {
    if (waiting.has(ch)) { waiting.delete(ch); total += 2; }
    else waiting.add(ch);
  }
  return total + (waiting.size > 0 ? 1 : 0);
}

